<template>
  <div class="topLeft">
    <div class="itemTop">
      <label class="itemTopLabel">统一待办</label>
      <div class="more" @click="gotoTaskCenter">
        <img class="moreImg" src="../assets/icon_2all_a.png"/>
        <label class="moreTitle">更多</label>
      </div>
    </div>
    <table class="itemTable">
      <tr v-for="task in taskList">
        <td class="tdPoint">•</td>
        <td class="tdTitle"><label class="labelTitle" @click="openTask(task.work)">{{task.title}}</label></td>
        <td class="tdStartTime"><label class="labelStartTime">{{task.startTime}}</label></td>
      </tr>
    </table>
  </div>
  <div class="topRight">
    <div class="itemTop">
      <label class="itemTopLabel">{{ appName }}</label>
      <div class="more" @click="openCMS">
        <img class="moreImg" src="../assets/icon_2all_a.png"/>
        <label class="moreTitle">更多</label>
      </div>
    </div>
    <div class="itemContentDiv" v-for="document in documentList" @click="openDocument(document.id)">
      <div class="itemTitle">{{document.title}}</div>
      <div class="itemBody">{{document.summary}} ...【详情】</div>
    </div>
  </div>
</template>

<script setup>
import {ref} from 'vue'
import {o2} from '@o2oa/component'

const documentList = ref([]);
const props = defineProps({
  appName: String
})
o2.Actions.load("x_cms_assemble_control").DocumentAction.	query_listWithFilterPaging(1,3,{"appNameList":[props.appName]}).then((json)=>{
  documentList.value = json.data;
});
const taskList = ref([]);
o2.Actions.load("x_processplatform_assemble_surface").TaskAction.V2ListPaging(1, 5).then((json)=>{
  taskList.value = json.data;
});
function openTask(id){
  o2.api.page.openWork(id);
}
function openDocument(id){
  o2.api.page.openDocument(id);
}
function openCMS(){
  o2.api.page.openCMS(appName);
}
function gotoTaskCenter(){
  o2.api.page.openApplication("process.workcenter");
}
</script>

