<template>
  <div>
    <!--1. 轮播默认显示3个,可以改成显示一个滑块  :slides-per-view="1"-->
    <!-- 5.自动轮播  加入:autoplay -->
    <swiper
        :modules="modules"
        :slides-per-view="1"
        :space-between="50"
        navigation
        :pagination="{ clickable: true }"
        :autoplay="{
			      delay: 1500,
			      disableOnInteraction: false,
			    }"
        @swiper="onSwiper"
        @slideChange="onSlideChange"
    >
      <!-- 4.swiper要v-for 遍历   图片改成自己的-->
      <swiper-slide v-for='(item,index) in arr' :key='index'>
        <img :src="item.imgsrc">
      </swiper-slide>

    </swiper>
  </div>

</template>

<script>
// 2.导入轮播组件 import Swiper core and required modules
// 加入Autoplay是开启自动轮播
import SwiperCore,{ Navigation, Pagination, Scrollbar, A11y , Autoplay} from 'swiper';
SwiperCore.use([Navigation, Pagination, Scrollbar, A11y , Autoplay]);
// Swiper Vue.js 组件
import { Swiper, SwiperSlide } from 'swiper/vue/swiper-vue.js';
// 压缩版css总样式
import "swiper/swiper-bundle.min.css"
import {o2} from "@o2oa/component";

export default {
  name: 'hotpic',
  data() {
    const imgList = [];
    o2.Actions.load("x_hotpic_assemble_control").HotPictureInfoAction.listForPage(1, 5, {}, function (json){
      debugger;
      json.data.each(function (item,index){
        imgList.push({id:index+1,imgsrc:item.url})
        //imgList.push({id:1,imgsrc:require("../assets/icon_2all_a.png")});
      })
    },null,false);
    debugger;
    return {
      arr:imgList,
    }
  },
  components: {
    Swiper,
    SwiperSlide,
  },
  setup() {
    const onSwiper = (swiper) => {
      console.log(swiper);
    };
    const onSlideChange = () => {
      console.log('slide change');
    };
    return {
      onSwiper,
      onSlideChange,
      modules: [Navigation, Pagination, Scrollbar, A11y],
    };
  },

}
</script>

<style scoped>
/*3. 更改组件样式 */
.swiper-slide {
  height: 262px;
  line-height: 300px;
  font-size: 30px;
  text-align: center;
  /* //轮播组件背景可以改颜色 */
  background-color: #FFFFFF;
}
/* 小圆点默认蓝色,可以改成白色,黑色 */
.swiper::v-deep .swiper-pagination .swiper-pagination-bullet {
  background: rgb(0, 0, 0);
}
.swiper::v-deep .swiper-pagination .swiper-pagination-bullet-active {
  background: rgb(255, 255, 255);
}

</style>

