<template>
  <div class="bannerContent">
    <div class="logoTitleDiv"><img class="logoTitleImg" src="../assets/logo_xxxxdw.png"/></div>
    <div class="bannerRight">
      <div class="navi">
        <label class="naviLabel">{{ lp.homePage }}</label>
        <label class="naviLabel" @click="gotoTaskCenter">{{ lp.taskCenter }}</label>
        <label class="naviLabel" @click="startProcess">{{ lp.processManage }}</label>
        <label class="naviLabel" @click="gotoAttendance">{{ lp.attendanceManage }}</label>
      </div>
      <div class="searchDiv">
        <input class="searchInput" @keyup.enter="doSearch()" type="text" v-model='searchInput'/>
      </div>
      <div class="logoutDiv" :title=lp.logout @click="logout"><img src="../assets/icon_kaiguan.png"/></div>
      <div class="profileDiv" :title=lp.profile @click="gotoProfile"><img src="../assets/icon_ren.png"/></div>
    </div>
  </div>
  <div class="welcomeDiv">
    <label class="welcomeLabel">{{ w_str }}</label>
  </div>
</template>

<script setup>
import {lp, o2} from '@o2oa/component'
import {ref} from 'vue'

const searchInput = ref('');

const userName = o2.api.session.user.name;
const week = ["","周一","周二","周三","周四","周五","周六","周日"];
const date = new Date();
const month = ["01月","02月","03月","04月","05月","06月","07月","08月","09月","10月","11月","12月"];
const welcome =  "您好，"+userName+"！今天是"+date.getUTCFullYear()+"年"+month[date.getMonth()]+date.getDate()+"日（"+week[date.getDay()]+"）";
const w_str = ref(welcome);

function doSearch(){
  o2.api.page.openApplication("ftsearch", {"query": searchInput.value});
}
function gotoTaskCenter(){
  o2.api.page.openApplication("process.workcenter");
}
function startProcess(){
  o2.requireApp([["process.TaskCenter", "lp."+o2.language], ["process.TaskCenter", ""]],"", function(){
    const obj = {
      "lp": MWF.xApplication.process.TaskCenter.LP,
      "content": o2.api.page.app.content,
      "addEvent": function(type, fun){

      },
      "getAction": function (callback) {
        if (!o2.api.page.action) {
          o2.api.page.action = MWF.Actions.get("x_processplatform_assemble_surface");
          if (callback) callback();
        } else {
          if (callback) callback();
        }
      },
      "desktop": layout.desktop,
      "refreshAll": function(){},
      "notice": o2.api.page.app.notice,
    }
    o2.JSON.get("../x_component_process_TaskCenter/$Main/default/css.wcss", function(data){
      obj.css = data;
    }, false);

    if (!o2.api.page.processStarter) o2.api.page.processStarter = new MWF.xApplication.process.TaskCenter.Starter(obj, {
      "onStartProcess": function(){

      }
    });
    o2.api.page.processStarter.load();
  }, true, true);
}
function gotoAttendance(){
  o2.api.page.openApplication("Attendance");
}
function gotoProfile(){
  o2.api.page.openApplication("Profile");
}
function logout(){
  o2.Actions.get("x_organization_assemble_authentication").logout(function(){
    window.location.reload();
  }.bind(this));
}
</script>

<style scoped>
 .bannerContent{
   background: #1462be;
   padding: 15px 0;
   position: relative;
   height: 70px;
 }
 .logoTitleDiv{
   height: 60px;
   width: 250px;
   float: left;
   margin: 0;
   cursor: pointer;
 }
 .logoTitleImg{
   margin: 0 0 0 15px;
   height: 100%;
 }
 .bannerRight{
   margin-left: 240px;
   height: 60px;
   overflow: hidden;
 }
 .naviLabel{
   float: left;
   font-size: 16px;
   color: #fff;
   width: 100px;
   text-align: center;
   margin-top: 18px;
   height: 22px;
   line-height: 22px;
   cursor: pointer;
   border-right: 1px solid #FFFFFF;
 }
 .searchDiv{
   float: right;
   margin-right: 270px;
   width: 300px;
 }
 .searchInput{
   height: 30px;
   width: 300px;
   border-radius: 8px;
   border: 1px solid #ccc;
   margin-top: 15px;
   position: absolute;
   float: right;
 }
 .profileDiv{
   float: right;
   margin-top: 18px;
   margin-right: 20px;
   cursor: pointer;
 }
 .logoutDiv{
   float: right;
   margin-top: 18px;
   margin-right: 30px;
   cursor: pointer;
 }
 .welcomeDiv{
   height: 40px;
   background: #ffffff;
   border-radius: 2px;
   text-align: center;
 }
 .welcomeLabel{
   float: left;
   margin: 10px 30px;
 }
</style>